modelBuilder.create-chart:
model -> {

// Only assemblies (parts built from other parts) are displayed. Single parts are not part of the
// diagram, but can be selected in the table sharing the selection with this diagram. Such a
// selection is kept when the diagram is rebuilt or extended by a CTRL-click in the diagram.
assemblies = $model.get(`test.flowchart:Product#buildInstructions`)
    .filter(p -> !$p.get(`test.flowchart:FlowNode#inputs`).isEmpty());

nodes = $assemblies.map(p -> flowSelection(
    userObject: $p,
    content: flowBorder(stroke: "#eccf33", thickness: 2, cssClass: "tlSelectionMarker",
    content: flowFill(fill: "#ffee95", cssClass: "tlSelectionMarker",
    content: flowPadding(all: 8,
    content: flowText(
        fontWeight: "bold",
        text: $p.get(`test.flowchart:FlowNode#name`)))))));

nodeByPart = $nodes.indexBy(n -> $n["userObject"]);

flowChart(
    root: flowPadding(all: 16,
        content: flowTree(
            nodes: $nodes,
            connections: $assemblies
                .map(p -> $p
                    .get(`test.flowchart:FlowNode#inputs`)
                    .filter(c -> $assemblies.containsElement($c))
                    .map(c -> flowConnection(
                        parent: $nodeByPart[$p],
                        child: $nodeByPart[$c])))
                .flatten()
        )
    )
);

}
